class Solution {
    public int countEven(int a, int b, int c) {
        int count = 0;
        if (isEven(a)) count++;
        if (isEven(b)) count++;
        if (isEven(c)) count++;
        return count;
    }

    private boolean isEven(int x) {
        return x % 2 == 0;
    }
}
